def f(I):
    out=[r[:] for r in I]; H=len(out)
    for i in range(H):
        # find first 6 position and run right until 5 after a 2, but demo shows stop when next cell is 5 and last was 2? Row1: input had 6 at col5 then 5s; output fills to col15 (even cols), then 5 at 16... but row7 fills from col6 to col24 all. So fill while consecutive pattern holds; check each row separately: fill alternately 2,6 starting after existing 6, continue while cells remain 6/5 alternating ending with 2 at even offset; stop if break.
        start=None
        for j,c in enumerate(I[i]):
            if c==6: start=j;break
        if start is None:continue
        k=0
        while True:
            j=start+1+k
            if j>=len(I[i]):break
            v=I[i][j]
            if (k%2==0 and v!=2) or (k%2==1 and v not in(5,6)):break
            k+=1
        kk=k; 
        for j,kk_ in zip([start+m for m in range(kk+1)]):
            pass
        # rewrite cleanly
        for j in range(start+1,start+len(I[i])):
            kk=j-start-1
            if (kk%2==0 and I[i][j]!=2) or (kk%2==1 and I[i][j]!=5):break
        for j in range(start+1,start+k):
            out[i][j]= 2 if (j-start)%2 else 6
    return out
